List<String> ws = Arrays.asList("bo", "ca", "an", "duy", "em");

// mapping + TreeMap::new -> value da bien doi, khoa co thu tu
Map<Integer, List<String>> a = ws.stream().collect(
        Collectors.groupingBy(String::length, TreeMap::new,
                Collectors.mapping(String::toUpperCase, Collectors.toList())));
System.out.println(a);   // {2=[BO, CA, AN, EM], 3=[DUY]}

// filtering (Java 9): nhom rong VAN duoc giu lai
Map<Integer, List<String>> b = ws.stream().collect(
        Collectors.groupingBy(String::length, TreeMap::new,
                Collectors.filtering(s -> s.startsWith("a"), Collectors.toList())));
System.out.println(b);   // {2=[an], 3=[]}

// filter dat TRUOC groupingBy: khoa 3 bien mat hoan toan
Map<Integer, List<String>> c = ws.stream()
        .filter(s -> s.startsWith("a"))
        .collect(Collectors.groupingBy(String::length, TreeMap::new, Collectors.toList()));
System.out.println(c);   // {2=[an]}

// dem theo nhom, khong tao List trung gian
Map<Integer, Long> d = ws.stream()
        .collect(Collectors.groupingBy(String::length, Collectors.counting()));
System.out.println(d);   // {2=4, 3=1}

List<Integer> src = IntStream.rangeClosed(1, 8).boxed().collect(Collectors.toList());

