ExecutorService pool = Executors.newFixedThreadPool(4);

// 1) submit: exception bi cat trong Future, KHONG in ra gi
Future<?> f = pool.submit((Runnable) () -> { throw new IllegalStateException("boom"); });
// neu khong ai goi f.get() -> loi bien mat hoan toan

try {
    f.get();                                  // day moi la luc loi noi len
} catch (ExecutionException e) {
    log.error("task that bai", e.getCause()); // getCause() moi la exception goc
}

// 2) execute: exception di toi UncaughtExceptionHandler -> in ra stderr
pool.execute(() -> { throw new IllegalStateException("boom2"); });
// Exception in thread "pool-1-thread-1" java.lang.IllegalStateException: boom2

// 3) Gan handler (va dat ten thread) cho moi thread cua pool
ThreadFactory tf = r -> {
    Thread t = new Thread(r, "order-worker");
    t.setUncaughtExceptionHandler((th, ex) -> log.error("uncaught tren " + th.getName(), ex));
    return t;
};

// 4) Logging: truyen exception lam tham so cuoi, khong noi chuoi
